                            t.HasCheckConstraint("CK_ProjectTasks_OpeningRounds", "\"Type\" NOT IN (8,9,10) OR (\"QuotationRound\" IS NULL AND \"DeadlineAt\" IS NULL AND \"WasOverdue\" IS NULL AND ((\"Type\" = 8 AND \"Area\" = 1) OR (\"Type\" IN (9,10) AND \"Area\" = 5)))");

